// ── Enums ──────────────────────────────────────
enum VehicleType { MOTORCYCLE, CAR, TRUCK }
enum SlotType    { SMALL, MEDIUM, LARGE }
enum SlotStatus  { FREE, OCCUPIED }

// ── ParkingSlot (Model) ────────────────────────
class ParkingSlot {
    private final String slotId;
    private final int floorNumber;
    private final int slotNumber;
    private final SlotType slotType;
    private SlotStatus status = SlotStatus.FREE;

    // State transition: FREE → OCCUPIED
    public synchronized void park() {
        if (status != SlotStatus.FREE)
            throw new IllegalStateException("Slot already occupied: " + slotId);
        status = SlotStatus.OCCUPIED;
    }

    // State transition: OCCUPIED → FREE
    public synchronized void free() {
        if (status != SlotStatus.OCCUPIED)
            throw new IllegalStateException("Slot already free: " + slotId);
        status = SlotStatus.FREE;
    }

    public boolean isAvailable() { return status == SlotStatus.FREE; }
    // getters omitted for brevity
}

// ── Ticket (Model — immutable after creation) ──
class Ticket {
    private final String ticketId;
    private final ParkingSlot slot;
    private final VehicleType vehicleType;
    private final String licensePlate;
    private final LocalDateTime entryTime;

    public Ticket(ParkingSlot slot, VehicleType vt, String plate) {
        this.ticketId = UUID.randomUUID().toString();
        this.slot = slot;
        this.vehicleType = vt;
        this.licensePlate = plate;
        this.entryTime = LocalDateTime.now();
    }

    public long getDurationMinutes() {
        return ChronoUnit.MINUTES.between(entryTime, LocalDateTime.now());
    }
    // getters omitted
}

// ── Fee Strategy (Strategy Pattern) ────────────
interface FeeStrategy {
    double calculateFee(long durationMinutes);
}

class HourlyFeeStrategy implements FeeStrategy {
    private final double ratePerHour;

    public HourlyFeeStrategy(double rate) { this.ratePerHour = rate; }

    @Override
    public double calculateFee(long minutes) {
        if (minutes <= 0) return 0;           // edge: immediate exit
        double hours = Math.ceil(minutes / 60.0);
        return hours * ratePerHour;
    }
}

// Extension: zero changes to ParkingLot needed
class TimeSensitiveFeeStrategy implements FeeStrategy {
    private final double weekdayRate, weekendRate;

    public TimeSensitiveFeeStrategy(double wd, double we) {
        this.weekdayRate = wd;
        this.weekendRate = we;
    }

    @Override
    public double calculateFee(long minutes) {
        double rate = LocalDate.now().getDayOfWeek().getValue() >= 6
            ? weekendRate : weekdayRate;
        return Math.ceil(minutes / 60.0) * rate;
    }
}

class Floor {
    private final int floorNumber;
    private final Map<SlotType, Queue<ParkingSlot>> availableSlots;
    private final ReentrantLock lock = new ReentrantLock();

    public Floor(int num, Map<SlotType, List<ParkingSlot>> slots) {
        this.floorNumber = num;
        this.availableSlots = new EnumMap<>(SlotType.class);
        slots.forEach((type, list) ->
            availableSlots.put(type, new LinkedList<>(list)));
    }

    // ── Atomic find-and-occupy (prevents double-booking) ──
    public Optional<ParkingSlot> findAndOccupy(SlotType type) {
        lock.lock();
        try {
            Queue<ParkingSlot> q = availableSlots.get(type);
            if (q == null || q.isEmpty()) return Optional.empty();
            ParkingSlot slot = q.poll();      // dequeue = nearest
            slot.park();                       // FREE → OCCUPIED
            return Optional.of(slot);
        } finally {
            lock.unlock();
        }
    }

    public void returnSlot(ParkingSlot slot) {
        lock.lock();
        try {
            slot.free();                       // OCCUPIED → FREE
            availableSlots.get(slot.getSlotType()).add(slot);
        } finally {
            lock.unlock();
        }
    }

    public int getAvailableCount(SlotType type) {
        return availableSlots.getOrDefault(type, Collections.emptyQueue()).size();
    }
}

public class ParkingLot {
    private static volatile ParkingLot instance;
    private final List<Floor> floors;
    private final ConcurrentHashMap<String, Ticket> activeTickets = new ConcurrentHashMap<>();
    private final FeeStrategy feeStrategy;

    // ── Double-checked locking Singleton ──
    public static ParkingLot getInstance() {
        if (instance == null) {
            synchronized (ParkingLot.class) {
                if (instance == null) instance = new ParkingLot();
            }
        }
        return instance;
    }

    // ── park() ────────────────────────────
    public Ticket park(VehicleType vType, String licensePlate) {
        if (licensePlate == null || licensePlate.isBlank())
            throw new IllegalArgumentException("License plate required");

        SlotType required = mapSlotType(vType);

        for (Floor floor : floors) {          // prefer ground floor
            Optional<ParkingSlot> slot = floor.findAndOccupy(required);
            if (slot.isPresent()) {
                Ticket ticket = new Ticket(slot.get(), vType, licensePlate);
                activeTickets.put(ticket.getTicketId(), ticket);
                return ticket;
            }
        }
        throw new ParkingFullException("No slots available for " + vType);
    }

    // ── exit() ────────────────────────────
    public double exit(String ticketId) {
        Ticket ticket = activeTickets.remove(ticketId);  // atomic
        if (ticket == null)
            throw new InvalidTicketException("Ticket not found: " + ticketId);

        double fee = feeStrategy.calculateFee(ticket.getDurationMinutes());
        int floorIdx = ticket.getSlot().getFloorNumber();
        floors.get(floorIdx).returnSlot(ticket.getSlot());
        return fee;
    }

    private SlotType mapSlotType(VehicleType v) {
        return switch (v) {
            case MOTORCYCLE -> SlotType.SMALL;
            case CAR        -> SlotType.MEDIUM;
            case TRUCK      -> SlotType.LARGE;
        };
    }
}
